## Why This Is Asked

Tests knowledge of robust sorting strategies used in production libraries. Combines quicksort behavior, 3-way partitioning for duplicates, and a guaranteed worst-case fallback with heapsort. Assesses pivot choice, in-place constraints, and complexity reasoning.

## Key Concepts

- Introsort: hybrid of quicksort with depth-based fallback to heapsort
- 3-way partitioning: <, =, > pivot to handle duplicates efficiently
- Depth limit: d = floor(2*log2(n)) prevents O(n^2) degeneration
- In-place implementation with O(log n) recursion overhead

## Code Example

```javascript
function introsort(arr) {
  const n = arr.length;
  const depthLimit = n > 1 ? Math.floor(2 * Math.log2(n)) : 0;

  function swap(i, j) {
    const t = arr[i]; arr[i] = arr[j]; arr[j] = t;
  }

  function heapSortSub(start, end) {
    const len = end - start;
    function heapify(i, heapSize) {
      let largest = i;
      while (true) {
        const l = 2 * i + 1;
        const r = l + 1;
        let idx = i;
        if (l < heapSize && arr[start + l] > arr[start + idx]) idx = l;
        if (r < heapSize && arr[start + r] > arr[start + idx]) idx = r;
        if (idx !== i) { [arr[start + i], arr[start + idx]] = [arr[start + idx], arr[start + i]]; i = idx; } else break;
      }
    }
    for (let i = Math.floor(len / 2) - 1; i >= 0; i--) heapify(i, len);
    for (let endIdx = len - 1; endIdx > 0; endIdx--) {
      swap(start, start + endIdx);
      heapify(0, endIdx);
    }
  }

  function quicksort3(start, end, depth) {
    if (end - start <= 1) return;
    if (depth <= 0) {
      heapSortSub(start, end);
      return;
    }
    const pivot = arr[start + Math.floor((start + end - 1) / 2)];
    let lt = start, i = start, gt = end - 1;
    while (i <= gt) {
      if (arr[i] < pivot) { swap(lt, i); lt++; i++; }
      else if (arr[i] > pivot) { swap(i, gt); gt--; }
      else { i++; }
    }
    quicksort3(start, lt, depth - 1);
    quicksort3(gt + 1, end, depth - 1);
  }

  quicksort3(0, n, depthLimit);
}
```

## Follow-up Questions

- How would you adapt this for parallel sorting on large arrays?
- What changes if stability is required while keeping O(n log n) average time?

## Why This Is Asked
Tests ability to combine arrays/linked lists (deques), hash maps, and a heap to maintain a sliding-window top-K efficiently.

## Key Concepts
- Sliding window, expiration, lazy deletions in a heap
- Per-user state via linked-list/deque and running sums
- Time/space trade-offs for real-time top-K

## Code Example
```javascript
class WaveTopK {
  constructor(W) {
    this.W = W;
    this.userMap = new Map(); // user_id -> {queue: [], sum}
    this.heap = new MaxHeap(); // stores [sum, user_id]
  }
  addEvent(userId, score, ts) {
    let entry = this.userMap.get(userId);
    if (!entry) {
      entry = { queue: [], sum: 0 };
      this.userMap.set(userId, entry);
    }
    entry.queue.push([ts, score]);
    entry.sum += score;
    this.heap.push([entry.sum, userId]);
  }
  topK(currentTime, K) {
    const seen = new Map();
    const res = [];
    while (res.length < K && !this.heap.isEmpty()) {
      const [sum, uid] = this.heap.pop();
      const ent = this.userMap.get(uid);
      if (!ent) continue;
      // expire check
      this.expireUser(uid, currentTime);
      if (ent.sum !== sum) {
        this.heap.push([ent.sum, uid]);
        continue;
      }
      res.push(uid);
    }
    // Reinsert popped elements
    for (const uid of res) this.heap.push([this.userMap.get(uid).sum, uid]);
    return res;
  }
  expireUser(userId, currentTime) {
    const ent = this.userMap.get(userId);
    if (!ent) return;
    while (ent.queue.length && ent.queue[0][0] <= currentTime - this.W) {
      const [, val] = ent.queue.shift();
      ent.sum -= val;
    }
  }
}
```

## Follow-up Questions
- How would you handle ties in topK?
- What changes if K is large relative to N?
- How would you adapt for variable window sizes per user?

